    const instrument=new T.Group();instrument.position.set(mastX,deck,mastZ);instrument.name='Rüzgâr Çorabı ve Kepçeli Ölçer';props.add(instrument);
    const steel=0x57727a,porcelain=0xe0deca,turquoise=0x258e91,copper=0xcd8048,brass=0xeab454,dark=0x31454c;
